// Envelope for a pool operation request (create, and in future update).
// Wraps the pool resource with request-level controls (idempotency key and
// deadline) that are not part of the pool resource itself.
// Ref: #/components/schemas/PoolRequest_v1
type PoolRequestV1 struct {
	Pool PoolV1 `json:"pool"`
	// Caller-supplied UUID v4 for idempotent deduplication (AIP-155).
	// Generated by CLH before the first attempt and reused for every retry
	// of the same logical create-pool request. Returned as the operationID
	// in the 202 response; poll GET /v1/operations/{operationId}.
	RequestId string `json:"requestId"`
	// Absolute UTC (RFC 3339) time by which this create-pool request must
	// complete. VCM rejects a request whose deadline is already in the past
	// and stops work with a deadline-exceeded error once it elapses.
	Deadline time.Time `json:"deadline"`
}

